#include <stdio.h>
#include <stdlib.h>
typedef struct BSTNode {
    int key;
    struct BSTNode *lchild, *rchild;
} BSTNode, *BSTree;
void Insert(BSTree *T, int key)
{
    if (*T == NULL) {
        *T = (BSTNode *)malloc(sizeof(BSTNode));
        (*T)->key = key;
        (*T)->lchild = (*T)->rchild = NULL;
    } else if (key < (*T)->key)
        Insert(&(*T)->lchild, key);
    else if (key > (*T)->key)
        Insert(&(*T)->rchild, key);
}
void InOrder(BSTree T)
{
    if (T != NULL) {
        InOrder(T->lchild);
        printf("%d ", T->key);
        InOrder(T->rchild);
    }
}

int main(void)
{
    BSTree T = NULL, p;
    int x, cnt;
    while (scanf("%d", &x) == 1 && x != 0)
        Insert(&T, x);
    InOrder(T);
    printf("\n");
    scanf("%d", &x);
    for (p = T, cnt = 1; p && p->key != x; cnt++)
        p = x < p->key ? p->lchild : p->rchild;
    printf("%d\n", p != NULL ? cnt : 0);
    return 0;
}

#include <stdio.h>
int main(void)
{
    int HT[20], m, p, n, i, key, h, cnt;
    int total = 0;
    scanf("%d%d%d", &m, &p, &n);
    for (i = 0; i < m; i++)
        HT[i] = -1;
    for (i = 0; i < n; i++) {
        scanf("%d", &key);
        h = key % p;
        cnt = 1;
        while (HT[h] != -1) {
            h = (h + 1) % m;
            cnt++;
        }
        HT[h] = key;
        total += cnt;
    }
    for (i = 0; i < m; i++)
        printf("%d ", HT[i]);
    printf("\n%.2f\n", (double)total / n);
    return 0;
}
